import os
from typing import Dict, List, Optional, Tuple

import requests


class TextContentSafetyError(Exception):
    pass


class AzureContentSafetyClient:
    def __init__(self, endpoint: Optional[str] = None, key: Optional[str] = None, api_version: str = "2024-09-01"):
        self.endpoint = (endpoint or os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT", "")).rstrip("/")
        self.key = key or os.getenv("AZURE_CONTENT_SAFETY_KEY", "")
        self.api_version = api_version
        if not self.endpoint:
            raise TextContentSafetyError("AZURE_CONTENT_SAFETY_ENDPOINT is required")
        if not self.key:
            raise TextContentSafetyError("AZURE_CONTENT_SAFETY_KEY is required")

    def analyze_text(self, text: str) -> Dict:
        url = f"{self.endpoint}/contentsafety/text:analyze?api-version={self.api_version}"
        headers = {
            "Content-Type": "application/json",
            "Ocp-Apim-Subscription-Key": self.key,
        }
        payload = {"text": text}
        resp = requests.post(url, headers=headers, json=payload, timeout=30)
        if resp.status_code >= 400:
            raise TextContentSafetyError(f"Azure Content Safety request failed: {resp.status_code} {resp.text}")
        return resp.json()


def _severity_threshold_value(threshold: str) -> int:
    mapping = {
        "safe": 0,
        "low": 1,
        "medium": 2,
        "high": 3,
    }
    if threshold is None:
        return 2
    if isinstance(threshold, int):
        return max(0, min(3, threshold))
    value = mapping.get(str(threshold).strip().lower())
    if value is None:
        raise ValueError(f"Invalid threshold: {threshold}")
    return value


def allow_text(
    text: str,
    thresholds: Optional[Dict[str, str]] = None,
    client: Optional[AzureContentSafetyClient] = None,
) -> Tuple[bool, Dict]:
    """
    Apply per-category severity thresholds to decide whether to allow text.

    thresholds keys can include:
      - Hate
      - SelfHarm
      - Sexual
      - Violence

    Threshold values can be: safe, low, medium, high
    The text is allowed only if every detected category severity is <= its threshold.
    """
    if not isinstance(text, str) or not text.strip():
        raise ValueError("text must be a non-empty string")

    thresholds = thresholds or {}
    client = client or AzureContentSafetyClient()
    result = client.analyze_text(text)

    categories = [
        ("Hate", "hate"),
        ("SelfHarm", "selfHarm"),
        ("Sexual", "sexual"),
        ("Violence", "violence"),
    ]

    normalized = {}
    allow = True

    for public_name, response_key in categories:
        threshold_value = _severity_threshold_value(thresholds.get(public_name, "medium"))
        category_info = result.get(response_key, {})
        severity = category_info.get("severity")
        if severity is None:
            severity = category_info.get("Severity")
        if severity is None:
            severity = 0
        if isinstance(severity, str):
            severity_map = {"safe": 0, "low": 1, "medium": 2, "high": 3}
            severity = severity_map.get(severity.strip().lower(), 0)
        severity = int(severity)

        normalized[public_name] = {"severity": severity, "threshold": threshold_value}
        if severity > threshold_value:
            allow = False

    return allow, {"provider": "azure-ai-content-safety", "analysis": result, "thresholds": normalized}
